export const diaValido = v => /^20\d{2}-(0[1-9]|1[0-2])-(0[1-9]|[12]\d|3[01])$/.test(v || '') && new Date(v+'T12:00:00Z').toISOString().slice(0,10)===v;
const dataHoraBRT = v => new Intl.DateTimeFormat('sv-SE',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}).format(new Date(v)).replace(' ','T');
