export function moverMes(mes,delta){if(!mesValido(mes))throw Error('Competência inválida.');const d=new Date(mes+'-15T12:00:00Z');d.setUTCMonth(d.getUTCMonth()+delta);return d.toISOString().slice(0,7);}
