export function fonteReferencia(link,origem='',id=''){
  let u;try{u=new URL(String(link||'').trim());}catch{throw Error('Informe o link direto da referência.');}
  if(u.protocol!=='https:')throw Error('Use um link https da referência.');
  let host=u.hostname.toLowerCase().replace(/^www\./,'').replace(/^m\./,'');
  const path=u.pathname.replace(/\/+$/,'');let hit;
  if(/(^|\.)instagram\.com$/.test(host)&&(hit=path.match(/^\/(?:p|reel|reels|tv)\/([A-Za-z0-9_-]+)/)))return 'instagram:'+hit[1];
  if((host==='youtu.be'||host.endsWith('youtube.com'))&&(hit=host==='youtu.be'?path.slice(1):u.searchParams.get('v')||path.match(/^\/(?:shorts|embed)\/([^/]+)/)?.[1]))return 'youtube:'+hit;
  if(host.endsWith('tiktok.com')&&(hit=path.match(/\/video\/(\d+)/)))return 'tiktok:'+hit[1];
  ['utm_source','utm_medium','utm_campaign','utm_content','utm_term','igsh','igshid','fbclid','si','feature'].forEach(k=>u.searchParams.delete(k));
  u.hash='';u.hostname=host;u.pathname=path||'/';u.searchParams.sort();
  return origem&&id?origem+':'+id:'url:'+u.toString();
}
export function contadores(refs,ciclo){
  const unicas=new Set();let incompletas=0,duplicadas=0;
  for(const r of refs){if(!r.link||!r.ideia||!r.autorPerfil){incompletas++;continue;}if(unicas.has(r.fonte)){duplicadas++;continue;}unicas.add(r.fonte);}
  return {recebidas:unicas.size,entregues:ciclo?.lote?.contagem||0,incompletas,duplicadas,ativas:refs.filter(r=>!r.excluido).length,triadas:refs.filter(r=>r.filtro).length,selecionadas:refs.filter(r=>!r.excluido&&r.selecionada).length,usadas:refs.filter(r=>(r.usos||[]).length).length,excluidas:refs.filter(r=>r.excluido).length};
}
