export function situacaoCalendarioI164(c,cal,erro=''){
 const base=c.criacao?.base,mes=c.competencia;
 if(!base)return {estado:'preparacao',titulo:'Preparação do calendário',etapa:'',pessoa:'',conferido:true};
 if(base!==c.documentos?.consolidadoEnviado||!estadoEtapas(c).consolidado)return {estado:'base_pendente',titulo:'Há uma base nova ou materiais para conferir',etapa:estadoEtapas(c).consolidado?'criacao':'consolidado',pessoa:estadoEtapas(c).consolidado?'Chris':'Amanda',conferido:true};
 const naoConferido=motivo=>({estado:'nao_conferido',titulo:'Conferir o andamento do calendário',etapa:'criacao',pessoa:'Chris',conferido:false,motivo});
 if(erro)return naoConferido('A leitura atual do calendário não foi confirmada.');
 if(!cal||cal.excluido||cal.planejamentoBasesI155?.[mes]!==base)return naoConferido('A base e o mês do calendário precisam ser conferidos.');
 const marca=cal.aprovacaoMeses?.[mes],status=marca?.status;
 if(status==='ajuste_interno')return {estado:status,titulo:'Chris está ajustando o calendário',etapa:'criacao',pessoa:'Chris',conferido:true,motivo:marca.motivoAjuste||'',em:marca.em||''};
 if(status==='aguardando_interna')return {estado:status,titulo:'Amanda precisa revisar esta versão',etapa:'revisao',pessoa:'Amanda',conferido:true,em:marca.em||''};
 if(status==='aprovado_interno')return {estado:status,titulo:'Revisado; falta conferir a liberação',etapa:'disponivel',pessoa:'Amanda',conferido:true};
 if(status==='liberado'){
  const foto=marca.retratoLiberadoV115,p=c.publicacaoAtual;
  const publicada=marca.aprovadoPor==='Amanda'&&!!marca.aprovadoEm&&foto?.mes===mes&&foto.publicadoEm===marca.aprovadoEm&&Array.isArray(foto.items)&&foto.items.some(x=>x&&!x.excluido);
  const mesma=publicada&&p?.base===base&&p.aprovadoEm===marca.aprovadoEm&&JSON.stringify(p.retrato)===JSON.stringify(foto);
  return {estado:mesma?'disponivel':'conferir_liberacao',titulo:mesma?'Versão atual liberada pelo fluxo oficial':'Liberação recebida; conferir o vínculo desta versão',etapa:mesma?'':'disponivel',pessoa:mesma?'':'Amanda',conferido:true};
 }
 return {estado:status||'rascunho',titulo:'Calendário em criação ou correção',etapa:'criacao',pessoa:'Chris',conferido:true};
}
export function etapasCorrentesI164(c){const e=estadoEtapas(c),a=c.andamentoCalendarioI164;if(!a||a.estado==='preparacao')return e;return {...e,criacao:['aguardando_interna','aprovado_interno','conferir_liberacao','disponivel'].includes(a.estado),revisao:['aprovado_interno','disponivel'].includes(a.estado),disponivel:a.estado==='disponivel'};}
