export function dependencias(c,etapa){
  const e=estadoEtapas(c),i=ETAPAS.findIndex(x=>x[0]===etapa);
  if(i<1)return [];
  // Cada cliente anda sozinho. Diagnóstico Premium não é um gate universal.
  return !e[ETAPAS[i-1][0]]?[ETAPAS[i-1][1]]:[];
}
export function conflitosAgenda(c,config={},ausencias=[]){
  const out=[],dias=config.dias||[1,2,3,4,5];let anterior='';
  for(const [etapa,titulo,padrao] of ETAPAS){const a=c.agenda?.[etapa]||{},p=a.responsavel||padrao;
    if(a.inicio&&a.prazo&&a.inicio>a.prazo)out.push(titulo+': início depois do prazo.');
    if(a.prazo){
      if(!diaValido(a.prazo)){out.push(titulo+': data inválida.');continue;}
      if(anterior&&a.prazo<anterior)out.push(titulo+': está antes da etapa anterior.');
      if(a.prazo>=c.competencia+'-01'&&etapa!=='disponivel')out.push(titulo+': planejamento avança para dentro da competência.');
      if(!dias.includes(new Date(a.prazo+'T12:00:00Z').getUTCDay())||(config.feriados||[]).includes(a.prazo))out.push(titulo+': fora dos dias de trabalho configurados.');
      if(ausencias.some(x=>!x.excluido&&(x.pessoa===p||x.nome===p||x.funcionario===p)&&String(x.inicio||x.dataInicio||'')<=a.prazo&&String(x.fim||x.dataFim||'9999')>=a.prazo))out.push(titulo+': '+p+' está indisponível.');
      anterior=a.prazo;
    }
  }return out;
}
export function cargaAgenda(ciclos,config={}){
  const mapa=new Map();for(const c of ciclos.filter(c=>c.incluido!==false))for(const [etapa,,padrao,unidade] of ETAPAS){const a=c.agenda?.[etapa],dia=a?.prazo;if(!dia)continue;const p=a.responsavel||padrao,k=[dia,p,etapa].join('|');if(!mapa.has(k))mapa.set(k,{dia,pessoa:p,etapa,unidade,planejado:0,realizado:0,clientes:[]});const l=mapa.get(k);l.planejado+=etapa==='pesquisa'?12:1;l.realizado+=estadoEtapas(c)[etapa]?(etapa==='pesquisa'?c.lote.contagem:1):0;l.clientes.push(c.clienteNome);}
  return [...mapa.values()].sort((a,b)=>(a.dia+a.pessoa).localeCompare(b.dia+b.pessoa)).map(l=>({...l,capacidade:config.capacidades?.[l.etapa]??null,conflito:config.capacidades?.[l.etapa]!=null&&l.planejado>config.capacidades[l.etapa]}));
}
