    q('[data-confirmacao]').innerHTML='<article role="alertdialog" aria-label="Conferir ação"><h3>Confere antes de seguir</h3><p class="texto">'+esc(mensagem)+'</p><div class="actions">'+btn('confirmarAcao','Confirmar esta ação')+btn('cancelarAcao','Voltar sem alterar')+'</div></article>';
    q('[data-confirmacao]').scrollIntoView({block:'center'});q('[data-confirmacao] button')?.focus();
